def walk(x,path=''):
 if isinstance(x,dict):
  for k,v in x.items():
   if k in ids:yield path+'/'+k,x
   yield from walk(v,path+'/'+k)
 elif isinstance(x,list):
  for i,v in enumerate(x):yield from walk(v,path+'/'+str(i))
 elif (isinstance(x,int) and str(x) in ids) or (isinstance(x,str) and (x in ids or x in urls)):yield path,x
for p,h in allow.items():
